#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    /**
     * 方法：一維動態規劃
     * 時間複雜度: O(n * target)
     * 空間複雜度: O(target)
     */
    bool canPartition(vector<int>& nums) {
        int total = accumulate(nums.begin(), nums.end(), 0);

        // 總和為奇數
        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;
        vector<bool> dp(target + 1, false);
        dp[0] = true;

        for (int num : nums) {
            // 從右往左更新
            for (int j = target; j >= num; j--) {
                dp[j] = dp[j] || dp[j - num];
            }
        }

        return dp[target];
    }

    /**
     * 優化版：加入提前終止
     */
    bool canPartition_optimized(vector<int>& nums) {
        int total = accumulate(nums.begin(), nums.end(), 0);

        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;
        int maxNum = *max_element(nums.begin(), nums.end());

        if (maxNum > target) {
            return false;
        }

        if (maxNum == target) {
            return true;
        }

        vector<bool> dp(target + 1, false);
        dp[0] = true;

        for (int num : nums) {
            for (int j = target; j >= num; j--) {
                dp[j] = dp[j] || dp[j - num];
                if (dp[target]) {
                    return true;
                }
            }
        }

        return dp[target];
    }
};

