import java.util.Arrays;

class Solution {
    /**
     * 方法：一維動態規劃
     * 時間複雜度: O(n * target)
     * 空間複雜度: O(target)
     */
    public boolean canPartition(int[] nums) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }

        // 總和為奇數
        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;

        for (int num : nums) {
            // 從右往左更新
            for (int j = target; j >= num; j--) {
                dp[j] = dp[j] || dp[j - num];
            }
        }

        return dp[target];
    }

    /**
     * 優化版：加入提前終止
     */
    public boolean canPartition_optimized(int[] nums) {
        int total = 0;
        int maxNum = 0;

        for (int num : nums) {
            total += num;
            maxNum = Math.max(maxNum, num);
        }

        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;

        if (maxNum > target) {
            return false;
        }

        if (maxNum == target) {
            return true;
        }

        boolean[] dp = new boolean[target + 1];
        dp[0] = true;

        for (int num : nums) {
            for (int j = target; j >= num; j--) {
                dp[j] = dp[j] || dp[j - num];
                if (dp[target]) {
                    return true;
                }
            }
        }

        return dp[target];
    }
}

